import json,concurrent.futures,urllib.request
rows=json.load(open('/workspace/freeplug-grants.json'))
extra=[('OWASP Top 10','https://owasp.org/www-project-top-ten/'),('Texas LLC basics','https://www.sos.state.tx.us/corp/businessstructure.shtml'),('Open Data Structures','https://opendatastructures.org/'),('Google SEO Starter Guide','https://developers.google.com/search/docs/fundamentals/seo-starter-guide'),('Stripe SaaS pricing','https://stripe.com/resources/more/saas-pricing-models-101'),('Texas State SBDC','https://sbdc.mccoy.txst.edu/about-us.html'),('Hello Alice','https://www.helloalice.com/small-business-grants-and-funding'),('SBA grants','https://www.sba.gov/loans/additional-funding-opportunities/grants/'),('Hays Caldwell EDP','https://hayscaldwelledp.com'),('$100M Offers','https://www.acquisition.com/books'),('Subscription web design guide','https://webnewbiz.com/subscription-web-design-business'),('The Mom Test','https://www.momtestbook.com/'),('Fanatical Prospecting','https://www.amazon.com/Fanatical-Prospecting-Conversations-Leveraging-Telephone/dp/1119144752'),('Website leasing','https://b63.eu/en/blog/website-leasing/'),('Pricing Creativity','https://www.winwithoutpitching.com/pricing-creativity/'),('Win Without Pitching','https://www.winwithoutpitching.com/manifesto/'),('Hourly Billing Is Nuts','https://jonathanstark.com/hbin'),('The Automatic Customer','https://www.amazon.com/Automatic-Customer-Subscription-Business-Anything/dp/1591847168'),('Built to Sell','https://www.amazon.com/Built-Sell-Creating-Business-Without/dp/1591845823'),('HubSpot Inbound Sales','https://academy.hubspot.com/courses/inbound-sales'),('HubSpot CRM','https://www.hubspot.com/products/crm'),('Never Split the Difference','https://www.blackswanltd.com/never-split-the-difference'),('Moz local SEO','https://moz.com/learn/seo/local'),('Google Business Profile Help','https://support.google.com/business/answer/7342169'),('Josh Hall Podcast','https://joshhall.co/podcast'),('The Futur','https://www.youtube.com/@thefutur'),('Google sender guidelines','https://support.google.com/a/answer/81126'),('Yahoo sender best practices','https://senders.yahooinc.com/best-practices/'),('CAN-SPAM','https://www.ecfr.gov/current/title-16/chapter-I/subchapter-C/part-316')]
def check(x):
 n,u=x
 try:
  r=urllib.request.urlopen(urllib.request.Request(u,headers={'User-Agent':'Mozilla/5.0'}),timeout=25); body=r.read(600000).decode(errors='ignore'); return {'name':n,'url':u,'code':r.status,'final':r.url,'text':body[:1000]}
 except Exception as e:return {'name':n,'url':u,'code':str(e)}
with concurrent.futures.ThreadPoolExecutor(max_workers=12) as ex: out=list(ex.map(check,[(r['name'],r['url']) for r in rows]+extra))
json.dump(out,open('/workspace/freeplug-link-checks.json','w'),indent=2)
for r in out:print(r['name'],r['code'],r.get('final',''))
